def minPath(grid, k):
    n = len(grid)
    queue = deque()

    for r in range(n):
        for c in range(n):
            queue.append((grid[r][c], r, c, [grid[r][c]]))

    while queue:
        val, r, c, path = queue.popleft()

        if len(path) == k:
            return path

        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
